  "diff-modulus-corner": "<div class=\"mx-auto max-w-sm rounded-xl border bg-indigo-50/40 p-4 dark:bg-indigo-950/20\"><svg viewBox=\"0 0 300 200\" class=\"w-full\" role=\"img\" aria-label=\"The graph of the absolute value function forms a V with a sharp corner at the origin; the left slope is minus one and the right slope is plus one, so the derivative does not exist there.\"><line x1=\"20\" y1=\"150\" x2=\"280\" y2=\"150\" class=\"stroke-slate-400\" stroke-width=\"0.8\"></line><line x1=\"150\" y1=\"20\" x2=\"150\" y2=\"188\" class=\"stroke-slate-400\" stroke-width=\"0.8\"></line><polyline points=\"31,31 150,150\" class=\"fill-none stroke-indigo-600 dark:stroke-indigo-300\" stroke-width=\"2.4\"></polyline><polyline points=\"150,150 269,31\" class=\"fill-none stroke-indigo-600 dark:stroke-indigo-300\" stroke-width=\"2.4\"></polyline><circle cx=\"150\" cy=\"150\" r=\"3.5\" class=\"fill-rose-500\"></circle><text x=\"80\" y=\"92\" class=\"fill-slate-600 dark:fill-slate-300\" font-size=\"11\">slope −1</text><text x=\"180\" y=\"92\" class=\"fill-slate-600 dark:fill-slate-300\" font-size=\"11\">slope +1</text><text x=\"150\" y=\"172\" class=\"fill-rose-600 dark:fill-rose-300\" font-size=\"10.5\" font-weight=\"600\" text-anchor=\"middle\">corner: LHD ≠ RHD</text><text x=\"150\" y=\"198\" class=\"fill-slate-500\" font-size=\"9.5\" text-anchor=\"middle\">continuous, NOT differentiable at 0</text></svg></div>",
