  "circ-circle-anatomy": "<div class=\"mx-auto max-w-sm rounded-xl border bg-indigo-50/40 p-4 dark:bg-indigo-950/20\"><svg viewBox=\"0 0 300 220\" class=\"w-full\" role=\"img\" aria-label=\"A circle showing its centre, a radius from the centre to the rim, a diameter passing through the centre (twice the radius), and a chord that joins two points on the circle without passing through the centre.\"><circle cx=\"150\" cy=\"110\" r=\"80\" class=\"fill-indigo-100/40 stroke-indigo-600 dark:fill-indigo-900/30 dark:stroke-indigo-300\" stroke-width=\"2\"></circle><line x1=\"70\" y1=\"110\" x2=\"230\" y2=\"110\" class=\"stroke-rose-500\" stroke-width=\"2\"></line><line x1=\"150\" y1=\"110\" x2=\"215.53216354311934\" y2=\"64.11388509191632\" class=\"stroke-emerald-600 dark:stroke-emerald-400\" stroke-width=\"2.5\"></line><line x1=\"89.20526338571734\" y1=\"162\" x2=\"210.79473661428267\" y2=\"162\" class=\"stroke-amber-500\" stroke-width=\"2\"></line><circle cx=\"150\" cy=\"110\" r=\"3.5\" class=\"fill-slate-700 dark:fill-slate-200\"></circle><text x=\"156\" y=\"124\" class=\"fill-slate-600 dark:fill-slate-300\" font-size=\"11\" font-weight=\"600\">C</text><text x=\"184.76608177155967\" y=\"83.05694254595815\" class=\"fill-emerald-700 dark:fill-emerald-300\" font-size=\"11\" font-weight=\"600\">r</text><text x=\"150\" y=\"102\" class=\"fill-rose-600 dark:fill-rose-300\" font-size=\"10.5\" font-weight=\"600\" text-anchor=\"middle\">diameter = 2r</text><text x=\"150\" y=\"178\" class=\"fill-amber-600 dark:fill-amber-300\" font-size=\"10.5\" font-weight=\"600\" text-anchor=\"middle\">chord</text></svg></div>",
