  "hd-elevation-triangle": "<div class=\"mx-auto max-w-sm rounded-xl border bg-indigo-50/40 p-4 dark:bg-indigo-950/20\"><svg viewBox=\"0 0 320 190\" class=\"w-full\" role=\"img\" aria-label=\"A right triangle. The observer stands at the left on the ground. A vertical object of height h stands at the right. The horizontal base d is the ground distance from the observer to the foot of the object. The slanted line of sight from the observer to the top of the object makes the angle of elevation theta with the ground. tan theta equals h over d.\"><line x1=\"38\" y1=\"150\" x2=\"276\" y2=\"150\" class=\"stroke-slate-400\" stroke-width=\"1\"></line><line x1=\"48\" y1=\"150\" x2=\"250\" y2=\"150\" class=\"stroke-indigo-600 dark:stroke-indigo-300\" stroke-width=\"2\"></line><line x1=\"250\" y1=\"150\" x2=\"250\" y2=\"44\" class=\"stroke-indigo-600 dark:stroke-indigo-300\" stroke-width=\"2\"></line><line x1=\"48\" y1=\"150\" x2=\"250\" y2=\"44\" class=\"stroke-emerald-600 dark:stroke-emerald-400\" stroke-width=\"2\" stroke-dasharray=\"5 3\"></line><path d=\"M 238 150 L 238 138 L 250 138\" class=\"fill-none stroke-slate-400\" stroke-width=\"1\"></path><path d=\"M 76 150 A 28 28 0 0 0 74.5 140.5\" class=\"fill-none stroke-amber-500\" stroke-width=\"1.6\"></path><circle cx=\"48\" cy=\"150\" r=\"3.4\" class=\"fill-slate-600 dark:fill-slate-300\"></circle><text x=\"82\" y=\"144\" class=\"fill-amber-700 dark:fill-amber-300\" font-size=\"12\" font-weight=\"600\">θ</text><text x=\"149\" y=\"166\" class=\"fill-indigo-700 dark:fill-indigo-300\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">d</text><text x=\"258\" y=\"97\" class=\"fill-indigo-700 dark:fill-indigo-300\" font-size=\"12\" font-weight=\"600\">h</text><text x=\"131\" y=\"91\" class=\"fill-emerald-700 dark:fill-emerald-400\" font-size=\"9.5\" text-anchor=\"middle\">line of sight</text><text x=\"42\" y=\"166\" class=\"fill-slate-500\" font-size=\"9\" text-anchor=\"middle\">observer</text><text x=\"160\" y=\"184\" class=\"fill-slate-500\" font-size=\"10\" text-anchor=\"middle\">tan θ = h / d</text></svg></div>",
  "hd-shadow-sun": "<div class=\"mx-auto max-w-sm rounded-xl border bg-indigo-50/40 p-4 dark:bg-indigo-950/20\"><svg viewBox=\"0 0 330 180\" class=\"w-full\" role=\"img\" aria-label=\"A vertical tower of fixed height casts two shadows. When the sun is high at 60 degrees elevation the shadow is short; when the sun is low at 45 degrees elevation the shadow is longer. Shadow length equals height times cotangent of the sun&#x27;s elevation.\"><line x1=\"20\" y1=\"138\" x2=\"318\" y2=\"138\" class=\"stroke-slate-400\" stroke-width=\"1\"></line><line x1=\"70\" y1=\"50\" x2=\"120.776\" y2=\"138\" class=\"stroke-amber-500\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"></line><line x1=\"70\" y1=\"50\" x2=\"158\" y2=\"138\" class=\"stroke-orange-500\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"></line><circle cx=\"56\" cy=\"34\" r=\"6\" class=\"fill-amber-400\"></circle><circle cx=\"40\" cy=\"54\" r=\"6\" class=\"fill-orange-400\"></circle><line x1=\"70\" y1=\"143\" x2=\"158\" y2=\"143\" class=\"stroke-orange-500\" stroke-width=\"3\"></line><line x1=\"70\" y1=\"143\" x2=\"120.776\" y2=\"143\" class=\"stroke-amber-500\" stroke-width=\"3\"></line><line x1=\"70\" y1=\"138\" x2=\"70\" y2=\"50\" class=\"stroke-indigo-600 dark:stroke-indigo-300\" stroke-width=\"3\"></line><path d=\"M 70 127 L 81 127 L 81 138\" class=\"fill-none stroke-slate-400\" stroke-width=\"1\"></path><text x=\"62\" y=\"94\" class=\"fill-indigo-700 dark:fill-indigo-300\" font-size=\"12\" font-weight=\"600\" text-anchor=\"end\">h</text><text x=\"95.388\" y=\"133\" class=\"fill-amber-700 dark:fill-amber-300\" font-size=\"9\" text-anchor=\"middle\">sun 60°</text><text x=\"157.388\" y=\"160\" class=\"fill-orange-700 dark:fill-orange-300\" font-size=\"9\" text-anchor=\"middle\">sun 45° — longer shadow</text><text x=\"165\" y=\"175\" class=\"fill-slate-500\" font-size=\"10\" text-anchor=\"middle\">s = h cot θ — lower sun, longer shadow</text></svg></div>",
